# Setting gate + assert_* API (return ToolError | None — never raise)
# ═══════════════════════════════════════════════════════════════════════════


def test_should_block_defaults_true(session: Session):
    assert should_block_auto_generated(session) is True
    assert should_block_auto_generated(None) is True


def test_should_block_config_false(session: Session):
    session.custom_config = {"config_json": {"edit": {"block_auto_generated": False}}}
    assert should_block_auto_generated(session) is False


def test_assert_editable_file_content_refuses():
    err = assert_editable_file_content("# @generated\nx = 1\n", "x.py")
    assert isinstance(err, ToolError)
    assert "auto-generated" in err.message
    assert "x.py" in err.message


def test_assert_editable_file_content_filename():
    err = assert_editable_file_content("plain content\n", "zz_generated.go")
    assert isinstance(err, ToolError)


def test_assert_editable_file_content_passes_handwritten():
    assert assert_editable_file_content("# normal module\nx = 1\n", "x.py") is None


def test_assert_editable_file_content_setting_disabled(session: Session):
    session.custom_config = {"config_json": {"edit": {"block_auto_generated": False}}}
    assert (
        assert_editable_file_content("# @generated\nx = 1\n", "x.py", session=session)
        is None
    )


def test_build_error_message():
    err = build_auto_generated_error("path/x.py", "@generated")
    assert isinstance(err, ToolError)
    assert "Cannot modify auto-generated file" in err.message
    assert "@generated" in err.message
    assert "allow_auto_generated" in err.message


async def test_assert_editable_file_missing_ok(tmp_path):
    # new files are fine
    assert await assert_editable_file(str(tmp_path / "new.py")) is None


async def test_assert_editable_file_generated_refused(tmp_path):
    f = tmp_path / "svc.py"
    f.write_bytes(b"# @generated\ndata = 1\n")
    err = await assert_editable_file(str(f))
    assert isinstance(err, ToolError)
    assert "auto-generated" in err.message


async def test_assert_editable_file_handwritten_ok(tmp_path):
    f = tmp_path / "svc.py"
    f.write_bytes(b"# hand written\ndata = 1\n")
    assert await assert_editable_file(str(f)) is None


async def test_assert_editable_file_setting_disabled(tmp_path, session: Session):
    session.custom_config = {"config_json": {"edit": {"block_auto_generated": False}}}
    f = tmp_path / "svc.py"
    f.write_bytes(b"# @generated\ndata = 1\n")
    assert await assert_editable_file(str(f), session=session) is None


async def test_marker_cache_refreshed_on_rewrite(tmp_path):
    """Rewriting a generated file to hand-written content must re-scan."""
    f = tmp_path / "mod.py"
    f.write_bytes(b"# @generated\ndata = 1\n")
    assert await assert_editable_file(str(f)) is not None

    # rewrite as hand-written; bump mtime so the (mtime_ns, size) key changes
    f.write_bytes(b"# totally hand written now\ndata = 2\n")
    future = time.time() + 5
    os.utime(f, (future, future))
    assert await assert_editable_file(str(f)) is None


async def test_marker_cache_serves_same_stat(tmp_path):
    f = tmp_path / "mod.py"
    f.write_bytes(b"# @generated\ndata = 1\n")
    assert await assert_editable_file(str(f)) is not None
    # second call hits the cache and still refuses
    assert await assert_editable_file(str(f)) is not None


async def test_generated_filename_refused_regardless_of_content(tmp_path):
    f = tmp_path / "zz_generated.deepcopy.go"
    f.write_bytes(b"package x\n")
    err = await assert_editable_file(str(f))
    assert isinstance(err, ToolError)
    assert "zz_generated.deepcopy.go" in err.message
